const ToastContext = React.createContext(null);

const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const addToast = useCallback((message, type = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 3000);
  }, []);

  const removeToast = useCallback((id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  return React.createElement(ToastContext.Provider, { value: { addToast } },
    children,
    React.createElement("div", { className: "fixed bottom-4 right-4 z-50 flex flex-col gap-2" },
      toasts.map(toast => (
        React.createElement("div", {
          key: toast.id,
          className: `px-4 py-2 rounded shadow-lg text-white flex items-center gap-2 ${
            toast.type === 'error' ? 'bg-red-600' : 
            toast.type === 'success' ? 'bg-green-600' : 'bg-stone-700'
          }`
        },
          toast.message,
          React.createElement("button", { onClick: () => removeToast(toast.id), className: "ml-2 hover:text-gray-200" },
            React.createElement(XMarkIcon, { className: "w-4 h-4" })
          )
        )
      ))
    )
  );
};

const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useToast must be used within a ToastProvider");
  return context;
};

