const TimeControls = ({ onAdvanceTime, onAddLog }) => {
    const [customHours, setCustomHours] = useState(0);
    const [customMinutes, setCustomMinutes] = useState(0);
    const [logTitle, setLogTitle] = useState("");

    const handleAddLog = () => {
        if (!logTitle.trim()) return;

        // Advance time if specified
        if (customHours > 0 || customMinutes > 0) {
             onAdvanceTime(customHours, customMinutes, logTitle);
        } else {
            onAddLog(logTitle);
        }

        setLogTitle("");
        setCustomHours(0);
        setCustomMinutes(0);
    };

    return React.createElement("div", { className: "bg-stone-800 border border-stone-700 p-4 rounded-lg mt-4" },
        React.createElement("div", { className: "flex gap-2 mb-4 overflow-x-auto pb-2" },
            [5, 15, 60, 240, 480].map(min => (
                React.createElement("button", {
                    key: min,
                    onClick: () => onAdvanceTime(0, min, `Zeit vergeht (${min < 60 ? min + ' Min' : min/60 + ' Std'})`),
                    className: "px-3 py-1 bg-stone-700 hover:bg-stone-600 text-stone-200 rounded text-sm whitespace-nowrap transition-colors"
                }, `+${min < 60 ? min + 'm' : min/60 + 'h'}`)
            ))
        ),
        React.createElement("div", { className: "flex gap-4 items-end" },
            React.createElement("div", { className: "flex-grow" },
                 React.createElement("input", {
                    type: "text",
                    placeholder: "Ereignisbeschreibung",
                    value: logTitle,
                    onChange: (e) => setLogTitle(e.target.value),
                    onKeyDown: (e) => e.key === 'Enter' && handleAddLog(),
                    className: "w-full bg-stone-900 border border-stone-600 text-stone-200 px-3 py-2 rounded focus:outline-none focus:border-amber-600"
                })
            ),
             React.createElement("div", { className: "flex gap-2 items-center" },
                 React.createElement("div", { className: "flex flex-col" },
                    React.createElement("label", { className: "text-[10px] text-stone-500 text-center mb-0.5" }, "STD"),
                    React.createElement("input", {
                        type: "number",
                        min: "0",
                        value: customHours,
                        onChange: (e) => setCustomHours(parseInt(e.target.value) || 0),
                        className: "w-16 bg-stone-900 border border-stone-600 text-stone-200 px-2 py-2 rounded text-center"
                    })
                 ),
                 React.createElement("div", { className: "flex flex-col" },
                     React.createElement("label", { className: "text-[10px] text-stone-500 text-center mb-0.5" }, "MIN"),
                     React.createElement("input", {
                        type: "number",
                        min: "0",
                        value: customMinutes,
