                    })
                 ),
                 React.createElement("button", {
                    onClick: handleAddLog,
                    className: "px-4 py-2 bg-amber-700 hover:bg-amber-600 text-white rounded font-bold font-medieval transition-colors h-[42px]" 
                }, "Hinzufügen")
             )
        )
    );
};

const App = () => {
    const [currentDate, setCurrentDate] = useState(new Date(1491, 2, 1, 8, 0)); // 1. Mar 1491, 08:00
    const [climateZone, setClimateZone] = useState('temperate');
    const [weather, setWeather] = useState(null);
    const [logs, setLogs] = useState([]);
    const { addToast } = useToast();

    // Initial Weather Generation
    useEffect(() => {
        if (!weather) {
            const newWeather = generateNewWeather(climateZone, currentDate);
            setWeather(newWeather);
        }
    }, [climateZone]); // Run when climate zone changes

    // Weather Update on Time Change
    const updateWeather = (newDate, forceNew = false) => {
        if (!weather) return;

        const hoursPassed = (newDate.getTime() - weather.date.getTime()) / (1000 * 60 * 60);

        // If we passed the "nextChangeHour" threshold or forced, generate new weather
        if (forceNew || newDate.getHours() >= weather.nextChangeHour || hoursPassed > 8 || newDate.getDate() !== weather.date.getDate()) {
             // Pass the old weather to ensure continuity
             const nextWeather = generateNewWeather(climateZone, newDate, weather);
             setWeather(nextWeather);
        } else {
            // Just update temperature based on time of day
            const updatedWeather = updateTemperatureForHour(weather, newDate.getHours(), climateZone, newDate);
            setWeather(updatedWeather);
        }
    };

    const advanceTime = (hours, minutes, title) => {
        const newDate = new Date(currentDate);
        newDate.setHours(newDate.getHours() + hours);
        newDate.setMinutes(newDate.getMinutes() + minutes);

        setCurrentDate(newDate);
        updateWeather(newDate);

        if (title) {
            const newLog = {
                id: Date.now(),
                date: newDate,
                title: title,
                type: 'event'
            };
            setLogs(prev => [...prev, newLog]);
        }
    };

    const addLog = (title) => {
        const newLog = {
            id: Date.now(),
            date: currentDate,
            title: title,
            type: 'note'
        };
        setLogs(prev => [...prev, newLog]);
    };

    const deleteLog = (id) => {
        setLogs(prev => prev.filter(l => l.id !== id));
        addToast("Eintrag gelöscht", "info");
    };

    // Helper for displaying date
    const formattedDate = useMemo(() => {
        const day = currentDate.getDate();
        const month = FANTASY_MONTHS[currentDate.getMonth()];
        const year = currentDate.getFullYear();
        return `${day}. ${month} ${year}`;
    }, [currentDate]);

    const sunlight = useMemo(() => calculateSunlight(currentDate, climateZone), [currentDate, climateZone]);

    return React.createElement("div", { className: "min-h-screen bg-stone-900 text-stone-200 p-6 max-w-4xl mx-auto" },
        React.createElement("header", { className: "mb-8 flex justify-between items-center border-b border-stone-700 pb-4" },
            React.createElement("div", null,
                React.createElement("h1", { className: "text-3xl font-medieval text-amber-500" }, "D&D Zeitmesser"),
                React.createElement("div", { className: "flex items-center gap-4 mt-2 text-stone-400" },
                     React.createElement("div", { className: "flex items-center gap-1" },
                        React.createElement(CalendarIcon, { className: "w-4 h-4" }),
                        React.createElement("span", { className: "text-lg font-bold text-stone-200" }, formattedDate)
                     ),
                     React.createElement("div", { className: "flex items-center gap-1" },
                        // Simple icon based on sunlight state
                        ['NIGHT_AM', 'NIGHT_PM'].includes(sunlight.state) ? React.createElement(MoonIcon, { className: "w-4 h-4 text-blue-300" }) : React.createElement(SunIcon, { className: "w-4 h-4 text-yellow-500" }),
                        React.createElement("span", { className: "text-xl font-mono font-bold text-stone-100" }, 
                            currentDate.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
                        )
                     )
                )
            ),
            React.createElement("select", {
                value: climateZone,
                onChange: (e) => setClimateZone(e.target.value),
                className: "bg-stone-800 border border-stone-600 text-stone-200 px-3 py-1 rounded text-sm focus:outline-none focus:border-amber-600"
            },
                CLIMATE_ZONES.map(zone => React.createElement("option", { key: zone.id, value: zone.id }, zone.name))
            )
        ),

        weather && React.createElement("div", { className: "bg-stone-800 border border-stone-700 rounded-lg p-6 mb-6 flex items-center justify-between relative overflow-hidden" },
             // Background "glow" based on weather type
             React.createElement("div", { className: `absolute inset-0 opacity-10 ${weather.type.includes('sunny') ? 'bg-yellow-500' : weather.type.includes('rain') ? 'bg-blue-900' : 'bg-gray-500'}` }),

             React.createElement("div", { className: "relative z-10 flex items-center gap-6" },
                React.createElement(weather.icon, { className: "w-16 h-16 text-stone-300" }),
                React.createElement("div", null,
                    React.createElement("h2", { className: "text-2xl font-medieval text-amber-500" }, weather.description),
                    React.createElement("div", { className: "flex items-center gap-4 mt-1" },
                        React.createElement("span", { className: "text-3xl font-bold text-stone-200" }, `${weather.temperature}°C`),
                        weather.effects && weather.effects.length > 0 && React.createElement("div", { className: "flex gap-1" },
                             weather.effects.map((eff, idx) => 
                                React.createElement("span", { key: idx, className: "px-2 py-0.5 bg-red-900/50 border border-red-800 text-red-200 text-xs rounded flex items-center gap-1", title: eff.description },
                                    React.createElement(WarningIcon, { className: "w-3 h-3" }),
                                    eff.name
                                )
                             )
                        )
                    )
                )
             )
        ),

        React.createElement(Timeline, { logs: logs, onDeleteLog: deleteLog }),
        React.createElement(TimeControls, { onAdvanceTime: advanceTime, onAddLog: addLog })
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
    React.createElement(ToastProvider, null, 
        React.createElement(App)
    )
);
